commands.text:
set -euo pipefail
uname -m
mkdir -p solver/dist
cp "$RUNNER_TEMP/x64/solver.mjs" solver/dist/solver.mjs
node --input-type=module -e "
  import { createHash } from 'node:crypto';
  import { readFileSync, writeFileSync } from 'node:fs';
  import { bytes } from './solver/dist/solver.mjs';
  const digest = createHash('sha256').update(bytes).digest('hex');
  const pinned = readFileSync('fixtures/solver.sha256', 'utf8').trim();
  if (digest !== pinned) {
    console.error('the x64 module embeds ' + digest + ', not the pinned ' + pinned);
    process.exit(1);
  }
  writeFileSync(process.env.RUNNER_TEMP + '/si_solver.wasm', bytes);
  console.log('the module embeds the pinned binary ' + digest);
"
node solver/lint.mjs "$RUNNER_TEMP/si_solver.wasm"
